use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Percent-encodes everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar (Howard Hinnant's civil_from_days algorithm).
fn civil_date(days_since_epoch: u64) -> (u64, u64, u64) {
    let z = days_since_epoch + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Read the clock once: this is the instant the run began.
        let started = wall_clock::now().seconds;
        let (y, m, d) = civil_date(started / 86_400);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        // Enrichment fetch, on every call. The record is intentionally not
        // used: the node's output is unchanged by it. `fetch` reports transport
        // failures as a value, so an unreachable enrichment service does not
        // fail the tick.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = http_client::fetch(&url);

        RunInfo { date, started }
    }
}

export!(Node);
